UNION ALL SELECT UNISTR('\064A\062C\064A\0628 \062E\0627\062F\0645 \0627\0644\062F\0648\0627\0645 \0639\0646 \0623\0633\0626\0644\062A\0643 \0628\0635\0644\0627\062D\064A\0627\062A \062D\0633\0627\0628\0643 \0641\064A\0647. \064A\0638\0647\0631 \0627\0644\0631\062F \0628\0639\062F \0625\0639\0627\062F\0629 \062A\062D\0645\064A\0644 \0627\0644\0635\0641\062D\0629\061B \0648\0625\0646 \0637\0627\0644 \0641\0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB. \0625\0631\0641\0627\0642 \0627\0644\0645\0644\0641\0627\062A \0648\062A\0646\0632\064A\0644 \0645\0627 \064A\0635\0646\0639\0647 \0627\0644\0645\0633\0627\0639\062F \0645\0646 \0632\0631 \0627\0644\0645\0633\0627\0639\062F \0641\064A \0623\0639\0644\0649 \0627\0644\0635\0641\062D\0629.') AR, TO_CHAR(UNISTR('The attendance server answers your questions with your account\0027s permissions there. The answer appears when the page reloads; if it takes long, press \00ABRefresh\00BB. Attaching files and downloading what the assistant makes are in the assistant button at the top of the page.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062C\064A\0628 \062E\0627\062F\0645 \062D\0627\0636\0631 \0639\0646 \0623\0633\0626\0644\062A\0643 \0628\0635\0644\0627\062D\064A\0627\062A \062D\0633\0627\0628\0643 \0641\064A\0647. \064A\0638\0647\0631 \0627\0644\0631\062F \0628\0639\062F \0625\0639\0627\062F\0629 \062A\062D\0645\064A\0644 \0627\0644\0635\0641\062D\0629\061B \0648\0625\0646 \0637\0627\0644 \0641\0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB. \0625\0631\0641\0627\0642 \0627\0644\0645\0644\0641\0627\062A \0648\062A\0646\0632\064A\0644 \0645\0627 \064A\0635\0646\0639\0647 \0627\0644\0645\0633\0627\0639\062F \0645\0646 \0632\0631 \0627\0644\0645\0633\0627\0639\062F \0641\064A \0623\0639\0644\0649 \0627\0644\0635\0641\062D\0629.') AR, TO_CHAR(UNISTR('The Hader server answers your questions with your account\0027s permissions there. The answer appears when the page reloads; if it takes long, press \00ABRefresh\00BB. Attaching files and downloading what the assistant makes are in the assistant button at the top of the page.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644 \0627\0644\0645\0648\0638\0641 \0645\0646 \0628\0648\0627\0628\0629 \0627\0644\0645\0624\0633\0633\0629 \062B\0645 \00AB\0627\0644\062F\062E\0648\0644 \0625\0644\0649 \0628\0648\0627\0628\062A\064A\00BB: \064A\0631\0649 \062D\0636\0648\0631\0647 \0627\0644\064A\0648\0645 \0648\0633\062C\0644\0647 \0627\0644\0634\0647\0631\064A\060C \0648\064A\0631\0633\0644 \0637\0644\0628\0627\062A\0647 \0648\064A\0631\0649 \0631\0635\064A\062F \0625\062C\0627\0632\0627\062A\0647. \0644\0627 \0643\0644\0645\0629 \0645\0631\0648\0631 \062E\0627\0635\0629 \0628\0627\0644\0628\0648\0627\0628\0629: \064A\0643\0641\064A \062F\062E\0648\0644\0647 \0625\0644\0649 \0623\0646\0638\0645\0629 \0627\0644\0645\0624\0633\0633\0629.') AR, TO_CHAR(UNISTR('An employee signs in from the organization\2019s portal, then \201CSign in to My portal\201D: they see today\2019s attendance and their month, send their requests and see their leave balance. No password of its own: signing in to the organization\2019s systems is enough.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644 \0627\0644\0645\0648\0638\0641 \0645\0646 \0628\0648\0627\0628\0629 \0627\0644\0645\0624\0633\0633\0629 \062B\0645 \00AB\0627\0644\062F\062E\0648\0644 \0625\0644\0649 \0628\0648\0627\0628\062A\064A\00BB: \064A\0631\0649 \062D\0636\0648\0631\0647 \0627\0644\064A\0648\0645 \0648\0633\062C\0644\0647 \0627\0644\0634\0647\0631\064A\060C \0648\064A\0631\0633\0644 \0637\0644\0628\0627\062A\0647 \0648\064A\0631\0649 \0631\0635\064A\062F \0625\062C\0627\0632\0627\062A\0647. \0644\0627 \0643\0644\0645\0629 \0645\0631\0648\0631 \062E\0627\0635\0629 \0628\0627\0644\0628\0648\0627\0628\0629: \064A\0643\0641\064A \062F\062E\0648\0644\0647 \0625\0644\0649 \0623\0646\0638\0645\0629 \0627\0644\0645\0624\0633\0633\0629. \0631\0627\0628\0637 \0628\0648\0627\0628\062A\064A \0627\0644\0645\0628\0627\0634\0631: f?p=&APP_ID.:77') AR, 'The employee comes in from the organisation''s portal, then Enter My portal: they see their attendance today and their monthly record, send their requests and see their leave balance. The portal has no password of its own: signing in to the organisation''s systems is enough. My portal''s own address: f?p=&APP_ID.:77' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644\0648\0646 \0628\0628\0631\064A\062F\0647\0645') AR, 'Sign in with their email' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644\0648\0646 \0628\062D\0633\0627\0628 \0645\0631\062A\0628\0637 \0628\0647\0645') AR, 'Sign in with a linked account' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\0648\064A') AR, 'By hand' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0631\0633\0644 \0625\0644\0649 \0627\0644\062C\0647\0627\0632') AR, 'Sending to the terminal' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0631\0649 \0645\0633\0624\0648\0644 \0627\0644\0642\0633\0645 \0648\0646\0627\0626\0628\0647 \0637\0644\0628\0627\062A \0627\0644\0625\062C\0627\0632\0629 \0648\0627\0644\0628\0635\0645\0629 \0627\0644\064A\062F\0648\064A\0629 \0648\0627\0644\0639\0645\0644 \0627\0644\0625\0636\0627\0641\064A \0644\0645\0648\0638\0641\064A \0647\0630\0627 \0627\0644\0642\0633\0645 \0648\0627\0644\0623\0642\0633\0627\0645 \0627\0644\062A\0627\0628\0639\0629 \0644\0647\060C \0648\064A\0639\062A\0645\062F\0648\0646\0647\0627\061B \0648\0644\0627 \064A\0631\0648\0646 \0637\0644\0628\0627\062A \063A\064A\0631\0647\0627. \0627\0644\0646\0627\0626\0628 \064A\0639\062A\0645\062F \0641\064A \0641\062A\0631\062A\0647 \0641\0642\0637 (\0641\0627\0631\063A = \062F\0627\0626\0645\0627\064B). \064A\062D\062A\0627\062C \0627\0644\062D\0633\0627\0628 \0623\064A\0636\0627\064B \0635\0644\0627\062D\064A\0629 \00AB\0627\0639\062A\0645\0627\062F \0627\0644\0637\0644\0628\0627\062A\00BB\060C \0648\0627\0644\0645\062F\064A\0631 \0627\0644\0639\0627\0645 \064A\0639\062A\0645\062F \0643\0644 \0627\0644\0623\0642\0633\0627\0645 \062F\0648\0646 \062A\0639\064A\064A\0646. \0627\0644\062D\0633\0627\0628\0627\062A \0645\0646 \0635\0641\062D\0629 \00AB\0627\0644\0645\0633\062A\062E\062F\0645\0648\0646\00BB.') AR, TO_CHAR(UNISTR('A department head and deputy see the leave, manual punch and overtime requests of this department\2019s employees and of the departments under it, and approve them; they see no other requests. A deputy approves only in their period (empty = always). The account also needs the \201CApprove requests\201D permission; the general manager approves all departments without being assigned. Accounts are on the \201CUsers\201D page.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0633\062A\0642\0628\0644 \0645\0646 \0627\0644\062C\0647\0627\0632') AR, 'Receiving from the terminal' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0635\0644 \0627\0644\062C\0647\0627\0632 \0625\0644\0649 \0627\0644\062E\0627\062F\0645 \0645\0646 \0627\0644\0639\0646\0648\0627\0646') AR, 'The terminal reaches the server from the address' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0646\062A\0638\0631 \0631\062F \062E\0627\062F\0645 \0627\0644\062F\0648\0627\0645\061B \0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB \0628\0639\062F \0642\0644\064A\0644.') AR, TO_CHAR(UNISTR('Waiting for the attendance server\0027s answer; press \00ABRefresh\00BB in a moment.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0646\062A\0638\0631 \0631\062F \062E\0627\062F\0645 \062D\0627\0636\0631\061B \0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB \0628\0639\062F \0642\0644\064A\0644.') AR, TO_CHAR(UNISTR('Waiting for the Hader server\0027s answer; press \00ABRefresh\00BB in a moment.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\062A\0627\0628\0639 \062D\0636\0648\0631\0647') AR, 'Tracked' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\062E\062A\0628\0631 \0647\0646\0627 \0627\0644\0627\062A\0635\0627\0644 \0628\062E\062F\0645\0629 \062A\064F\0637\0644\0628 \0645\0646 \0642\0627\0639\062F\0629 \0627\0644\0628\064A\0627\0646\0627\062A. \062E\062F\0645\0629 \062A\064F\0637\0644\0628 \0645\0646 \0627\0644\0645\062A\0635\0641\062D \062A\064F\062E\062A\0628\0631 \0628\0633\0624\0627\0644 \0641\064A \00AB\0627\0644\0645\0633\0627\0639\062F \0627\0644\0630\0643\064A\00BB.') AR, TO_CHAR(UNISTR('Here the connection of a service called from the database is tested. A service called from the browser is tested by asking the \00ABAI assistant\00BB a question.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0642\0627\0633...') AR, 'Measuring...' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0646\0634\0623 \0625\0646 \0644\0645 \064A\0648\062C\062F\061B \064A\064F\0643\0641\0649 \0628\0627\0644\0631\0645\0632 \0625\0646 \0648\064F\062C\062F') AR, 'Created if it does not exist; the code alone is enough when given' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0646\0641\064E\0651\0630') AR, 'Running' EN FROM DUAL) s ON (t.AR = s.AR)
  WHEN MATCHED THEN UPDATE SET EN = s.EN WHERE t.EN <> s.EN
  WHEN NOT MATCHED THEN INSERT (AR, EN) VALUES (s.AR, s.EN);
  COMMIT;
END;
/

-- ---------------------------------------------------------------- hdr_core.pks
CREATE OR REPLACE PACKAGE HDR_CORE AS
  -- Hader for Oracle APEX (native): settings, text helpers, the terminal command queue and the
  -- distribution of employees, templates and photos to the terminals of their areas.

  TYPE t_kv IS TABLE OF NVARCHAR2(4000) INDEX BY VARCHAR2(60);

  -- the Hader release these objects belong to: the APEX app warns when it is newer than them
  c_version CONSTANT VARCHAR2(20) := '2.4.25';

  -- TRUE while a terminal's upload is stored: the change triggers stay quiet (the upload distributes
  -- what it changes itself and marks its own days)
  g_quiet BOOLEAN := FALSE;

  -- settings ------------------------------------------------------------
  FUNCTION setting (p_key IN VARCHAR2, p_default IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  PROCEDURE set_setting (p_key IN VARCHAR2, p_value IN VARCHAR2);
  FUNCTION on_ (p_key IN VARCHAR2) RETURN BOOLEAN;           -- a Y/N setting
  FUNCTION writing RETURN BOOLEAN;                           -- changes may be sent to the terminals
  FUNCTION server_tz (p_sn IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;   -- hours, for the terminals
  -- the clock the terminals keep: the database's time in the zone set for the terminal (adms.timezone); the
  -- database's own clock when none is set
  FUNCTION local_now (p_sn IN VARCHAR2 DEFAULT NULL) RETURN DATE;

  -- text ------------------------------------------------------------------
  FUNCTION to_text (p_body IN BLOB) RETURN NCLOB;           -- UTF-8, older Arabic code page per line
  FUNCTION to_utf8 (p_text IN NCLOB) RETURN BLOB;
  FUNCTION kv (p_text IN NVARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN t_kv;   -- keys lower-case
  FUNCTION kv_big (p_line IN NCLOB, p_key IN VARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN CLOB;
  FUNCTION get (p_kv IN t_kv, p_key IN VARCHAR2, p_default IN NVARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  FUNCTION num (p_value IN NVARCHAR2, p_default IN NUMBER DEFAULT 0) RETURN NUMBER;
  FUNCTION parse_time (p_text IN NVARCHAR2) RETURN DATE;
  FUNCTION valid_pin (p_pin IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION field (p_text IN VARCHAR2, p_n IN PLS_INTEGER, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN VARCHAR2;  -- n-th, empty ones count
  FUNCTION tsv_safe (p_value IN NVARCHAR2) RETURN NVARCHAR2;  -- no tab / newline inside a value
  FUNCTION dev_time (p_when IN DATE) RETURN NUMBER;           -- the terminals' compact clock value
  FUNCTION b64_blob (p_text IN CLOB) RETURN BLOB;             -- base64 text (line breaks and all) to its bytes

  -- the hours of an employee's working day on a date (hader/day_hours.py): of the rules hr.day_hours_rules that hold
  -- (hours|from|to|attendance type ids|department codes|name, ";" between), the one starting last; else the hours the
  -- employee's attendance type that day has most often; else hr.day_hours (7)
  FUNCTION day_hours (p_emp IN VARCHAR2, p_day IN DATE) RETURN NUMBER;

  -- terminal options (Key=Value lines kept in HDR_DEVICES.OPTIONS) ----------
  FUNCTION opt (p_sn IN VARCHAR2, p_key IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE apply_info (p_sn IN VARCHAR2, p_info IN t_kv);    -- merge INFO / options keys

  -- command queue -----------------------------------------------------------
  FUNCTION is_change (p_content IN NVARCHAR2) RETURN BOOLEAN;   -- anything but INFO / DATA QUERY
  FUNCTION queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL) RETURN NUMBER;
  PROCEDURE queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL);
  PROCEDURE requeue_stale (p_minutes IN NUMBER DEFAULT 15, p_max_attempts IN NUMBER DEFAULT 3);

  -- command texts -------------------------------------------------------------
  -- as much of a name as a terminal's name field holds (24 bytes: about 12 Arabic letters), never half a letter
  FUNCTION terminal_name (p_name IN NVARCHAR2, p_bytes IN NUMBER DEFAULT 24) RETURN NVARCHAR2;
  FUNCTION whole_words (p_held IN NVARCHAR2, p_full IN NVARCHAR2) RETURN BOOLEAN;
  FUNCTION name_bytes (p_sn IN VARCHAR2) RETURN NUMBER;
  FUNCTION cmd_user (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_user_delete (p_emp_code IN VARCHAR2) RETURN NCLOB;
  FUNCTION cmd_query (p_table IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_query_attlog (p_from IN DATE, p_to IN DATE) RETURN NCLOB;

  -- employees on terminals ------------------------------------------------------
  FUNCTION uses_biodata (p_sn IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION push_employee (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_with_bio IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  FUNCTION sync_device (p_sn IN VARCHAR2) RETURN NUMBER;     -- every employee of its area (checks capacity)
  FUNCTION employee_changed (p_emp_code IN VARCHAR2, p_old_areas IN VARCHAR2 DEFAULT NULL,
                             p_with_bio IN BOOLEAN DEFAULT FALSE) RETURN NUMBER;   -- p_old_areas: 'id,id'
  FUNCTION employee_removed (p_emp_code IN VARCHAR2, p_areas IN VARCHAR2) RETURN NUMBER;
  -- people, every kind of template and the photos a terminal holds; p_again 'Y' (asked by a person): table
  -- queries tried once more even if the terminal refused them before
  FUNCTION pull_bio (p_sn IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL, p_again IN VARCHAR2 DEFAULT 'N') RETURN NUMBER;
  -- the terminal sends everything it holds again by itself: its marks cleared, its options read again
  FUNCTION resend_everything (p_sn IN VARCHAR2) RETURN NUMBER;
  -- it refused a table query (-1004): remembered, the other queries waiting closed, everything asked the other way
  PROCEDURE no_table_queries (p_sn IN VARCHAR2);
  FUNCTION bio_delete (p_emp_code IN VARCHAR2, p_kinds IN VARCHAR2, p_fingers IN VARCHAR2 DEFAULT NULL,
                       p_terminals IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  PROCEDURE distribute_user (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE distribute_template (p_bio_id IN NUMBER, p_source_sn IN VARCHAR2);
  -- The card picture (HADER_EMP_PHOTOS with SOURCE HAND, DEVICE or NULL) is what a terminal shows when the
  -- employee punches. The recognition photo (HDR_BIO_PHOTOS; SOURCE CAPTURE where it stands in on the pages)
  -- is what it learns the face from, and is never sent as the card picture.
  PROCEDURE distribute_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE withdraw_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);   -- the terminals drop theirs
  PROCEDURE userpic_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2);   -- the chosen one again (not in a loop)
  -- a terminal holding the person without the name kept here (enrolled there by number only) or with another
  -- one is sent it (not in a loop); p_held: the name it holds
  PROCEDURE name_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2, p_held IN NVARCHAR2);
  FUNCTION is_recognition_photo (p_emp_code IN VARCHAR2, p_pic IN BLOB) RETURN BOOLEAN;
  PROCEDURE distribute_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_source_sn IN VARCHAR2);
  -- the recognition photo to every terminal of the employee's areas (they learn the face from it); how many
  FUNCTION send_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  PROCEDURE mark_dirty (p_emp_code IN VARCHAR2, p_day IN DATE);
  PROCEDURE mark_days (p_emp_code IN VARCHAR2, p_from IN DATE, p_to IN DATE);   -- past and today only
  PROCEDURE mark_pending (p_kind IN VARCHAR2, p_key IN VARCHAR2, p_added IN VARCHAR2 DEFAULT NULL,
                          p_removed IN VARCHAR2 DEFAULT NULL, p_deleted IN BOOLEAN DEFAULT FALSE,
                          p_from IN DATE DEFAULT NULL);

  -- terminal settings sent as commands ---------------------------------------------
  PROCEDURE set_server (p_sn IN VARCHAR2, p_host IN VARCHAR2, p_port IN NUMBER, p_reboot IN BOOLEAN DEFAULT TRUE);
  PROCEDURE set_clock (p_sn IN VARCHAR2, p_when IN DATE DEFAULT NULL);
  PROCEDURE simple (p_sn IN VARCHAR2, p_action IN VARCHAR2);  -- info, check, reboot, clear_log, clear_photo, clear_data
  PROCEDURE set_option (p_sn IN VARCHAR2, p_key IN VARCHAR2, p_value IN NVARCHAR2);
  PROCEDURE enroll (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_finger IN NUMBER DEFAULT 0);

  -- errors raised to APEX pages
  e_read_only EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_read_only, -20601);
  e_capacity EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_capacity, -20602);
END HDR_CORE;
/

-- ---------------------------------------------------------------- hdr_license.pks
CREATE OR REPLACE PACKAGE HDR_LICENSE AS
  -- The activation key of Hader for Oracle APEX, checked in the database itself (no Hader server, Oracle 11g and
  -- later, no DBMS_CRYPTO needed): the key the vendor signs (hader/license.py, RSA PKCS#1 v1.5 with SHA-256), bound
  -- to this database (db_code). The free edition takes FREE_TERMINALS terminals; a key takes the number it says.

  FREE_TERMINALS CONSTANT PLS_INTEGER := 2;

  -- this database, as a key is made for it: shown on the settings page, sent to the vendor
  FUNCTION db_code RETURN VARCHAR2;
  -- FULL (the institution's own install: no limit) or FREE (the public edition)
  FUNCTION edition RETURN VARCHAR2;
  -- how many terminals this edition takes: NULL = no limit (the full edition, or a key without a limit)
  FUNCTION terminals_allowed RETURN NUMBER;
  -- the key's fields when it is valid for this database, else raises -20990 with the reason
  PROCEDURE check_key (p_key IN VARCHAR2, p_plan OUT VARCHAR2, p_terminals OUT NUMBER, p_expires OUT VARCHAR2);
  -- a key given on the settings page: checked, then kept (license.key)
  PROCEDURE set_key (p_key IN VARCHAR2);

  -- the building blocks, open for the tests
  FUNCTION sha256 (p_data IN RAW) RETURN RAW;
  FUNCTION rsa_public (p_sig IN RAW, p_n IN VARCHAR2, p_r2 IN VARCHAR2, p_np IN NUMBER) RETURN RAW;
  FUNCTION verify (p_payload IN RAW, p_sig IN RAW, p_n IN VARCHAR2 DEFAULT NULL, p_r2 IN VARCHAR2 DEFAULT NULL,
                   p_np IN NUMBER DEFAULT NULL) RETURN BOOLEAN;
  FUNCTION b64url (p_text IN VARCHAR2) RETURN RAW;
END HDR_LICENSE;
/

-- ---------------------------------------------------------------- hdr_adms.pks
CREATE OR REPLACE PACKAGE HDR_ADMS AS
  -- What the terminals talk to: ORDS hands every /iclock/* request to handle() (see hdr_ords.sql).
  --
  --   GET  /iclock/cdata?SN=..&options=all        -> settings block (handshake)
  --   POST /iclock/cdata?SN=..&table=ATTLOG       -> punches
  --   POST /iclock/cdata?SN=..&table=OPERLOG      -> users, templates, photos, operation log
  --   GET  /iclock/getrequest?SN=..               -> heartbeat; answered with C:<id>:<command> lines
  --   POST /iclock/devicecmd?SN=..                -> results of those commands
  --   POST /iclock/querydata?SN=..&tablename=..   -> answers to DATA QUERY tablename=..
  --   GET  /iclock/rtdata?SN=..&type=time         -> the server clock

  PROCEDURE handle (p_path IN VARCHAR2, p_method IN VARCHAR2, p_body IN BLOB DEFAULT NULL);

  -- the same without HTTP (tests, and replaying a stored request)
  FUNCTION process (p_path IN VARCHAR2, p_method IN VARCHAR2, p_query IN VARCHAR2, p_ip IN VARCHAR2,
                    p_body IN BLOB, p_status OUT NUMBER) RETURN NCLOB;

  FUNCTION verify_name (p_verify IN NUMBER) RETURN VARCHAR2;
  FUNCTION state_name (p_state IN NUMBER) RETURN VARCHAR2;
  -- punch lines kept aside with a database error ('error <code>', before an upgrade or a lock let them through)
  -- saved again; the number of punches added. NULLs: every terminal, the last 90 days
  FUNCTION replay_rejects (p_sn IN VARCHAR2 DEFAULT NULL, p_from IN DATE DEFAULT NULL) RETURN NUMBER;
  PROCEDURE purge;   -- old traffic and rejected lines
  -- a line as the logs keep it: no password, card number, communication key, template or picture
  FUNCTION masked (p IN VARCHAR2) RETURN VARCHAR2;
END HDR_ADMS;
/

-- ---------------------------------------------------------------- hdr_engine.pks
CREATE OR REPLACE PACKAGE HDR_ENGINE AS
  -- Attendance calculation (the same rules as Hader): for every employee and day it resolves the
  -- timetables (one-day override > personal schedule > department schedule > none), matches punches
  -- to the check-in / check-out windows and works out late, early leave, absence, worked time,
  -- overtime, leave and holidays. Results go to HADER_ATT_DAILY.

  -- calculate a period (all employees, or one) and store it
  PROCEDURE calc (p_from IN DATE, p_to IN DATE, p_emp_code IN VARCHAR2 DEFAULT NULL);
  -- what changed since the last time (new punches, leave, schedules): HDR_DIRTY
  PROCEDURE calc_dirty;
  -- employee-days to calculate again (a day's change can move the neighbouring night shift)
  PROCEDURE touch_period (p_emp_code IN VARCHAR2, p_from IN DATE, p_to IN DATE);
  PROCEDURE touch_all (p_from IN DATE, p_to IN DATE);

  -- one day as text "status|worked|late|..." (tests and the day details of the plug-ins)
  FUNCTION explain (p_emp_code IN VARCHAR2, p_day IN DATE) RETURN VARCHAR2;
  -- a day's punches as the program's reports write them: each one of the next morning marked (+1)
  FUNCTION punch_list (p_punches IN VARCHAR2, p_first IN DATE, p_day IN DATE) RETURN VARCHAR2 DETERMINISTIC;
END HDR_ENGINE;
/

-- ---------------------------------------------------------------- hdr_alerts.pks
CREATE OR REPLACE PACKAGE HDR_ALERTS AS
  -- The alerts of the Hader program (hader/alerts.py) inside the database, for the bell of APEX app 141:
  -- the same rules (HDR_SETTINGS alerts.<rule>.<field>, shared with the program), the same words, and each
  -- event told once (HDR_NOTIFICATIONS.AKEY, keyed as the program's alert log). What is meant for the managers
  -- reaches the bell; the program itself still tells the employees (its portal) and sends e-mail and Telegram.

  -- every minute, from HDR_JOBS.tick (after today's results are calculated)
  PROCEDURE tick;

  -- the pages of APEX app 141 a notification opens
  PAGE_DASHBOARD CONSTANT NUMBER := 1;
  PAGE_DEVICES   CONSTANT NUMBER := 6;
  PAGE_LEAVES    CONSTANT NUMBER := 11;
  PAGE_OVERTIME  CONSTANT NUMBER := 28;
  PAGE_MANUAL    CONSTANT NUMBER := 30;
  PAGE_LATE      CONSTANT NUMBER := 46;
  PAGE_ABSENT    CONSTANT NUMBER := 47;
  PAGE_EXCEPTION CONSTANT NUMBER := 55;

  -- the words of an alert, as the program writes them ({name}, {time} ... filled in)
  FUNCTION title (p_kind IN VARCHAR2) RETURN NVARCHAR2;
  FUNCTION body (p_kind IN VARCHAR2, p_name IN NVARCHAR2 DEFAULT NULL, p_time IN VARCHAR2 DEFAULT NULL,
                 p_minutes IN NUMBER DEFAULT NULL, p_device IN NVARCHAR2 DEFAULT NULL, p_what IN NVARCHAR2 DEFAULT NULL,
                 p_when IN NVARCHAR2 DEFAULT NULL, p_present IN NUMBER DEFAULT NULL, p_expected IN NUMBER DEFAULT NULL,
                 p_late IN NUMBER DEFAULT NULL, p_absent IN NUMBER DEFAULT NULL, p_offline IN NUMBER DEFAULT NULL)
    RETURN NVARCHAR2;

  -- an absence or a missing check-out is told this many minutes after the shift begins / ends at the earliest
  -- (the program's alerts.AFTER_SHIFT_MINUTES)
  AFTER_SHIFT CONSTANT NUMBER := 30;

  -- notifications older than this many days go (HDR_JOBS, once a day)
  KEEP_DAYS CONSTANT NUMBER := 90;
  PROCEDURE purge;
  -- a terminal's clock set to the server's on its return (HDR_ADMS, when the terminal says it did): told once, if
  -- the rule device_clock is on
  PROCEDURE clock_set (p_sn IN VARCHAR2);
  -- the Hader server set (or found right) a returning terminal's clock: APEX's bell says so too, once a return
  PROCEDURE clock_told (p_sn IN VARCHAR2, p_key IN VARCHAR2, p_what IN NVARCHAR2);
END HDR_ALERTS;
/

-- ---------------------------------------------------------------- hdr_jobs.pks
CREATE OR REPLACE PACKAGE HDR_JOBS AS
  -- The background work of Hader for Oracle APEX, run every minute by the scheduler job HDR_TICK
  -- (hdr_scheduler.sql): changes to the terminals, attendance calculation, the alerts, the HR import and
  -- the requests of the "Hader sync" button.

  PROCEDURE tick;

  -- employees, departments and leave from the HR views (HADER_V_EMPLOYEES / _DEPARTMENTS / _LEAVES)
  FUNCTION import_employees RETURN VARCHAR2;
  FUNCTION import_leaves RETURN VARCHAR2;

  -- changed people / terminals / company rules noted by the triggers
  PROCEDURE apply_pending;

  -- one request of HADER_REQUESTS (the button runs it at once; the job runs those inserted otherwise)
  PROCEDURE run_request (p_id IN RAW);
  PROCEDURE run_requests;
  -- run it now in the background (a one-off scheduler job), so the page does not wait; the
  -- every-minute job takes it anyway if this cannot start
  PROCEDURE start_request (p_id IN RAW);

  -- Hader for Oracle APEX takes over (native.active = Y): installed over a schema the Hader program wrote to,
  -- it stands still until this. The same punch found twice in HADER_PUNCHES is moved to HDR_PUNCHES_DUPLICATES
  -- (kept, not lost) and the punch index made; HDR_SEQ moves past the punch numbers already there.
  FUNCTION activate RETURN VARCHAR2;
  FUNCTION active RETURN BOOLEAN;

  -- the punches not handed yet to the HR system's own punches table (hr_table.*), as the Hader program's
  -- live send did: ID = base + PUNCH_ID, numbers unknown to HR wait, a refused row never holds up the others
  FUNCTION hr_table_push RETURN VARCHAR2;

  -- the same work as a request, for APEX processes: SYNC / PUNCHES / EMPLOYEES / LEAVES / RECALC
  FUNCTION do_request (p_kind IN VARCHAR2, p_emp_code IN VARCHAR2 DEFAULT NULL, p_from IN DATE DEFAULT NULL,
                       p_to IN DATE DEFAULT NULL) RETURN VARCHAR2;
  -- bridge mode (the Hader server owns the terminals, clock.owner = hader): the commands still waiting in
  -- HDR_COMMANDS from before (pending, or sent and never answered), which no terminal will fetch from this database
  -- any more, are deleted. Run once after the gateway exit:
  --   BEGIN DBMS_OUTPUT.PUT_LINE(HDR_JOBS.purge_gateway_commands); END;
  -- Returns how many were deleted.
  FUNCTION purge_gateway_commands RETURN NUMBER;
  -- one day of both engines (HDR_V_ENGINE_COMPARE) summed up into HDR_ENGINE_COMPARE_LOG (the job does yesterday
  -- once a day while compare.on = Y)
  PROCEDURE compare_day (p_day IN DATE);
END HDR_JOBS;
/

-- ---------------------------------------------------------------- hdr_policy.pks
CREATE OR REPLACE PACKAGE HDR_POLICY AS
  -- Dated versions of the timetables, the shifts (their cycle and their days) and the attendance rules: an edit of
  -- the working hours never changes the days before it. The program's rules (hader/policy_history.py), the same
  -- versions (HDR_TIMETABLE_VERSIONS, HDR_SHIFT_VERSIONS, HDR_RULE_VERSIONS), read by HDR_ENGINE:
  -- * the first edit keeps what applied before as the baseline, from the beginning of time;
  -- * an ordinary save (a form of APEX app 141, the settings) applies from today; the first one keeps the baseline
  --   only once a day before today has something calculated (a punch, a manual punch, a schedule of any kind).
  --   Saves of one day make one version;
  -- * a dated edit starts on its first day and stays open until the next edit starts, or ends on its last day:
  --   from the day after, what it set comes back to what applied just before it (but what an open edit made
  --   inside the period set stays). A period inside which another edit starts is refused;
  -- * each edit keeps what it set itself and every version is rebuilt from the edits (replay), so an edit dated
  --   between others never undoes a later one.
  -- Scopes: 'timetable' (target TT_ID), 'shift' (SHIFT_ID), 'rules' (target 0).
  -- Values travel as "KEY=value" lines (CHR(10)): the columns of HDR_TIMETABLES (CHECK_IN 'HH24:MI', MUST_IN 'Y'/'N',
  -- ...), a shift's CYCLE_UNIT, CYCLE and DAYS ('day:tt,day:tt', day 0 = Monday of week 1), the att.* settings as
  -- HDR_SETTINGS holds them. Refusals are ORA-206xx with an Arabic - English message for the page.

  OPEN_END  CONSTANT DATE := DATE '2199-12-31';     -- a schedule without a last day stays open until another one
  BEGINNING CONSTANT DATE := DATE '0001-01-01';     -- a baseline's first day

  -- a dated edit from p_from to p_to (both days counted; NULL: open). Returns the edit's VER_ID.
  FUNCTION save_edit (p_scope IN VARCHAR2, p_target IN NUMBER, p_from IN DATE, p_to IN DATE, p_reason IN NVARCHAR2,
                      p_values IN NVARCHAR2, p_actor IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- what applies on a day, and the row itself (HDR_TIMETABLES ...), as "KEY=value" lines
  FUNCTION values_at (p_scope IN VARCHAR2, p_target IN NUMBER, p_day IN DATE) RETURN NVARCHAR2;
  FUNCTION live_values (p_scope IN VARCHAR2, p_target IN NUMBER) RETURN NVARCHAR2;
  -- one value of such lines
  FUNCTION value_of (p_lines IN NVARCHAR2, p_key IN VARCHAR2) RETURN NVARCHAR2;

  -- an ordinary save of a timetable or a shift (APEX forms): p_before = live_values taken just before it.
  -- What it changed applies from today; the days before keep what they had.
  PROCEDURE saved (p_scope IN VARCHAR2, p_target IN NUMBER, p_before IN NVARCHAR2, p_actor IN VARCHAR2 DEFAULT NULL);
  -- an ordinary save of one rule (HDR_UI.set_value), just before it is set
  PROCEDURE rule_saving (p_key IN VARCHAR2, p_value IN VARCHAR2, p_actor IN VARCHAR2 DEFAULT NULL);
  -- versions written by the Hader server (hader/native_write.py): the stored results are worked out again from
  -- p_from (not before the first day with a stored result)
  PROCEDURE recalculate (p_from IN DATE);

  -- schedules: no last day (NULL) is open (OPEN_END). A new one trims what the employee / department had in its
  -- days (the one before ends the day before it starts). A started one keeps its shift and first day: only its last
  -- day moves, from yesterday on. Returns the schedule's id.
  FUNCTION schedule_save (p_id IN NUMBER, p_emp_code IN VARCHAR2, p_shift IN NUMBER, p_start IN DATE, p_end IN DATE)
    RETURN NUMBER;
  FUNCTION dept_schedule_save (p_id IN NUMBER, p_dept IN VARCHAR2, p_shift IN NUMBER, p_start IN DATE, p_end IN DATE)
    RETURN NUMBER;
  -- 'emp' / 'dept': a started schedule ends yesterday (returns that day, so the days calculated keep it); one not
  -- started yet goes (NULL); one wholly in the past goes only with p_past = 'Y' (correcting a mistake)
  FUNCTION schedule_end (p_kind IN VARCHAR2, p_id IN NUMBER, p_past IN VARCHAR2 DEFAULT 'N') RETURN DATE;

  -- removing: a shift in schedules, or a timetable used by a shift, an earlier version of one or a one-day schedule,
  -- is refused (the days calculated with it would change); otherwise it goes with its versions
  FUNCTION timetable_use (p_id IN NUMBER) RETURN NVARCHAR2;   -- where it is used; NULL: nowhere
  PROCEDURE timetable_delete (p_id IN NUMBER);
  PROCEDURE shift_delete (p_id IN NUMBER);

  e_refused EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_refused, -20630);
END HDR_POLICY;
/

-- ---------------------------------------------------------------- hdr_ui.pks
CREATE OR REPLACE PACKAGE HDR_UI AS
  -- What the Hader plug-ins of APEX pages read and do (terminals, an employee's biometrics, settings).
  -- Runs with the rights of the Hader schema: the APEX parsing schema needs only EXECUTE on it
  -- (HDR_UI.grant_to). Answers are JSON in plain ASCII (\u escapes), whatever the database character set.
  -- Errors are raised as ORA-206xx with an Arabic - English message for the page.

  -- terminals -------------------------------------------------------------------------------
  FUNCTION devices RETURN CLOB;
  FUNCTION commands (p_sn IN VARCHAR2, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;
  -- p_action: server (a1 host, a2 port, a3 Y/N restart) / clock / info / check / reboot / reload_options /
  --           clear_log / clear_photo / clear_data / sync (every person of its area) / pull (everything it holds) /
  --           update (a1 name, a2 area id, a3 Y/N enabled) / cancel (waiting commands) / retry (failed commands) /
  --           forget (remove the terminal from the list) / punches (a1 from, a2 to: the punches of a period) /
  --           option (a1 a setting of the terminal's own, a2 its value)
  FUNCTION device_do (p_sn IN VARCHAR2, p_action IN VARCHAR2, p_a1 IN NVARCHAR2 DEFAULT NULL,
                      p_a2 IN VARCHAR2 DEFAULT NULL, p_a3 IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- what is set for a terminal (its device form): English name, counted for attendance or not, time zone (hours,
  -- empty: the setting), seconds between its requests, how often and when it sends punches, at once or not.
  -- Returns 1 when the terminal is asked to read its settings again
  FUNCTION device_settings (p_sn IN VARCHAR2, p_alias_en IN VARCHAR2, p_attendance IN VARCHAR2,
                            p_time_zone IN VARCHAR2, p_heartbeat IN VARCHAR2, p_interval IN VARCHAR2,
                            p_times IN VARCHAR2, p_realtime IN VARCHAR2) RETURN NUMBER;
  PROCEDURE set_write (p_on IN VARCHAR2);   -- Y / N: changes may be sent to the terminals

  -- one employee on the terminals ------------------------------------------------------------
  FUNCTION employee (p_emp_code IN VARCHAR2) RETURN CLOB;
  -- p_action: areas (a1 = area ids 'id,id') / enroll (a1 terminal, a2 type 1 finger 2/9 face 8 palm 7 vein, a3 finger 0-9) /
  --           pull (read from the terminals of the areas) / push (send again with templates and photos) /
  --           remove (delete from the terminals of the areas)
  FUNCTION employee_do (p_emp_code IN VARCHAR2, p_action IN VARCHAR2, p_a1 IN VARCHAR2 DEFAULT NULL,
                        p_a2 IN VARCHAR2 DEFAULT NULL, p_a3 IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- several employees at once, as the program's employees page: p_codes their numbers (',' or spaces); p_action
  -- set_department (p_a1 the department) / set_areas, add_areas (p_a1 the area ids 'id,id') / resign (p_a1 the
  -- date YYYY-MM-DD, today when empty) / reinstate / sync (to their area terminals again) / unsync (off them, kept
  -- here) / delete. By whoever edits employees; returns what was done.
  FUNCTION employees_batch (p_user IN VARCHAR2, p_action IN VARCHAR2, p_codes IN VARCHAR2,
                            p_a1 IN VARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  -- one row of the employees' Excel file (the program's template): NEW or UPDATED, otherwise why not (nothing
  -- changed). The department by its code, then its name, made when not there; a new employee in the first area;
  -- one already here keeps what the row leaves empty. Never commits: the page checks a file by rolling back.
  FUNCTION employee_import (p_user IN VARCHAR2, p_code IN VARCHAR2, p_name IN NVARCHAR2 DEFAULT NULL,
                            p_name_en IN VARCHAR2 DEFAULT NULL, p_dept_code IN VARCHAR2 DEFAULT NULL,
                            p_dept IN NVARCHAR2 DEFAULT NULL, p_position IN NVARCHAR2 DEFAULT NULL,
                            p_card IN VARCHAR2 DEFAULT NULL, p_hire IN VARCHAR2 DEFAULT NULL,
                            p_mobile IN VARCHAR2 DEFAULT NULL, p_email IN VARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  -- the schedule of several employees (p_codes: their numbers) for a day or a period (p_from .. p_to, a year at
  -- most): the timetables p_tts ('id,id'), none = a day off; what they had in those days is replaced. Returns how
  -- many employees. As the program's temporary schedule (POST /api/temp-schedules); never commits
  FUNCTION temp_set (p_codes IN VARCHAR2, p_from IN DATE, p_to IN DATE DEFAULT NULL, p_tts IN VARCHAR2 DEFAULT NULL)
    RETURN NUMBER;
  -- A page's report as a file, as the program exports its reports (hader/reports.py to_xlsx and iter_csv):
  -- sheet_start (Excel: the organisation, the title and period above the table; p_csv 'Y': a CSV file), then the
  -- cells of each row (p_kind 's' text, 'n' a number, 'h' a heading, p_width its column's width) and sheet_row,
  -- then the file. Excel takes 1,048,576 rows a sheet (p_sheet_rows): the rest go on further sheets
  PROCEDURE sheet_start (p_title IN NVARCHAR2, p_period IN NVARCHAR2 DEFAULT NULL, p_rtl IN VARCHAR2 DEFAULT 'Y',
                         p_csv IN VARCHAR2 DEFAULT 'N', p_sheet_rows IN PLS_INTEGER DEFAULT 1048576);
  PROCEDURE sheet_cell (p_value IN NVARCHAR2, p_kind IN VARCHAR2 DEFAULT 's', p_width IN NUMBER DEFAULT NULL);
  PROCEDURE sheet_row;
  FUNCTION sheet_finish RETURN BLOB;
  FUNCTION photo (p_emp_code IN VARCHAR2) RETURN BLOB;          -- the card picture, else the recognition photo

  -- card pictures (HADER_EMP_PHOTOS: what a terminal shows when the employee punches; not the recognition
  -- photo it learns the face from). One chosen here goes to the terminals of the employee's areas and a
  -- terminal does not replace it. The functions return how many terminals are told.
  FUNCTION card_photo (p_emp_code IN VARCHAR2) RETURN BLOB;     -- the card picture only
  -- a JPEG named by the employee number (1234.jpg): NULL when taken, otherwise why not
  FUNCTION card_import (p_file_name IN VARCHAR2, p_data IN BLOB) RETURN VARCHAR2;
  FUNCTION card_from_recognition (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  FUNCTION card_delete (p_emp_code IN VARCHAR2) RETURN NUMBER;  -- the terminals remove theirs too

  -- recognition photos (HDR_BIO_PHOTOS: the face photos a terminal learns a face from) -------------------
  FUNCTION bio_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN BLOB;
  -- a JPEG named by the employee number (1234.jpg, 1234_face.jpg): NULL when taken, otherwise why not;
  -- p_send = 'Y' sends it on to the terminals of the employee's areas
  FUNCTION photo_import (p_file_name IN VARCHAR2, p_data IN BLOB, p_send IN VARCHAR2 DEFAULT 'N') RETURN VARCHAR2;
  FUNCTION photo_send (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  PROCEDURE photo_delete (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9, p_face IN VARCHAR2 DEFAULT 'N');

  -- the bell of APEX app 141 (HDR_ALERTS) ------------------------------------------------------
  -- the latest notifications, which of them this user has read, and how many of the last 30 days are unread
  FUNCTION notes (p_user IN VARCHAR2, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;
  -- one read (p_id), or every one of the last 30 days (p_id NULL)
  PROCEDURE notes_read (p_user IN VARCHAR2, p_id IN NUMBER DEFAULT NULL);
  -- how many of the last 30 days this user has not read (the count notes() gives: the app bar's figure)
  FUNCTION notes_unread (p_user IN VARCHAR2) RETURN NUMBER;
  -- Y / N: a notification of this kind, about this employee (NULL: none) of this department, reaches this user, as
  -- notes() lists it (APEX page 69: (select ... from dual) in its query)
  FUNCTION note_shown (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_emp_code IN VARCHAR2, p_dept_code IN VARCHAR2)
    RETURN VARCHAR2;

  -- the Hader assistant in APEX app 141 (HDR_AI_CHAT) ---------------------------------------------
  -- the page asks and reads; the Hader server, connected to this schema, answers (hader/ai/apex.py) and writes
  -- the reply as it grows. Every call is for one APEX user and sees that user's conversations only.
  -- p_files: the numbers of the files attached to it (ai_upload), separated by commas; without a question, the
  -- files are read
  FUNCTION ai_ask (p_user IN VARCHAR2, p_conv IN NUMBER, p_question IN VARCHAR2,
                   p_files IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;   -- the request
  -- a file attached to the next question: its number, until it is sent (ai_unupload takes it back)
  -- sent in parts (a page's request holds only so much): the first without p_id gives the number, the last says
  -- p_last 'Y'; a file sent at once is one part
  FUNCTION ai_upload (p_user IN VARCHAR2, p_name IN VARCHAR2, p_data IN BLOB, p_id IN NUMBER DEFAULT NULL,
                      p_last IN VARCHAR2 DEFAULT 'Y') RETURN NUMBER;
  PROCEDURE ai_unupload (p_user IN VARCHAR2, p_id IN NUMBER);
  FUNCTION ai_upload_get (p_user IN VARCHAR2, p_id IN NUMBER, o_name OUT VARCHAR2, o_mime OUT VARCHAR2) RETURN BLOB;
  -- run (p_run = 'Y') or decline a proposal shown in the answer to request p_req
  FUNCTION ai_decide (p_user IN VARCHAR2, p_req IN NUMBER, p_action IN NUMBER, p_run IN VARCHAR2) RETURN NUMBER;
  PROCEDURE ai_stop (p_user IN VARCHAR2, p_req IN NUMBER);
  PROCEDURE ai_drop (p_user IN VARCHAR2, p_conv IN NUMBER);      -- forget a conversation (here and in Hader)
  FUNCTION ai_poll (p_user IN VARCHAR2, p_req IN NUMBER) RETURN CLOB;   -- one request: its state and reply
  FUNCTION ai_list (p_user IN VARCHAR2) RETURN CLOB;                     -- the conversations, newest first
  FUNCTION ai_open (p_user IN VARCHAR2, p_conv IN NUMBER) RETURN CLOB;   -- one conversation, every question
  -- a file the assistant made for the user (HDR_AI_FILES): its content, name and type; NULL when not theirs
  FUNCTION ai_file (p_user IN VARCHAR2, p_id IN NUMBER, o_name OUT VARCHAR2, o_mime OUT VARCHAR2) RETURN BLOB;
  -- the assistant's settings, read, saved or tested by the Hader server for a system administrator: p_request is
  -- {"method": GET / PUT / POST, "path": "/api/ai/config" or "/api/ai/test", "body": ...}; the reply is read with
  -- ai_poll. A key typed in it is kept only until the Hader server takes the request.
  FUNCTION ai_config (p_user IN VARCHAR2, p_request IN VARCHAR2) RETURN NUMBER;

  -- whose requests (leave, manual punches, overtime) a user sees and decides: the program's hader/approvals.py ------
  -- An APEX user is the account of the same name (HDR_USERS, kept by the Hader server; others added in the app).
  -- The general manager (attendance.approve_all, or system.admin) decides every department; anyone else with
  -- attendance.approve those of the departments they head or stand in for today (HDR_APPROVERS, both dates counted,
  -- none = always) and of the departments under them; with no such department, none. Without attendance.approve
  -- nobody decides anything and the request pages show every request, as before. Employees without a department are
  -- the general manager's alone. While no account is known at all (HDR_USERS empty) the schema's own jobs and scripts
  -- may everything; a user signed in to APEX never: no account, no permission.
  -- Inside APEX the signed-in user counts (p_user is taken only outside it, from the schema's owner).
  FUNCTION permissions RETURN VARCHAR2;                                                -- the program's permissions
  FUNCTION may (p_user IN VARCHAR2, p_permission IN VARCHAR2) RETURN VARCHAR2;          -- Y / N
  -- who may enter APEX app 141: A an active account of that name (its pages by its permissions), E no account but an
  -- employee the database knows (their own portal page only), N nobody (a disabled account included)
  FUNCTION member (p_user IN VARCHAR2) RETURN VARCHAR2;
  -- the public demo (HDR_SETTINGS demo.public = Y, HDR_DEMO.set_public): every account but demo.admins is a visitor
  -- who looks and tries but deletes nothing and holds no system.admin / users.manage. Off on every other installation.
  FUNCTION public_demo RETURN VARCHAR2;                                -- Y / N
  FUNCTION visitor (p_name IN VARCHAR2) RETURN VARCHAR2;               -- Y: this account is a demo visitor
  FUNCTION look_only RETURN VARCHAR2;                                  -- Y: the APEX user signed in is a visitor
  FUNCTION look_only_text RETURN NVARCHAR2;                            -- the refusal, Arabic and English
  PROCEDURE guard;                                                     -- ORA-20698 (the refusal) for a visitor
  -- the first administrator of APEX app 141, from SQL Workshop, while no account is known at all
  PROCEDURE first_admin (p_user IN VARCHAR2);
  FUNCTION request_shown (p_user IN VARCHAR2, p_dept_code IN VARCHAR2) RETURN VARCHAR2;  -- Y / N: on the request pages
  FUNCTION request_decides (p_user IN VARCHAR2, p_emp_code IN VARCHAR2) RETURN VARCHAR2; -- Y / N
  -- the accounts that decide a request (p_kind leave / manual / overtime): active, attendance.approve over the
  -- employee's department, never the employee's own account; comma separated (the approval tasks' potential owners
  -- of the APEX 26.2 demo edition, apex/build_app262.py). Read for any account, not only the signed-in one.
  FUNCTION request_approvers (p_kind IN VARCHAR2, p_id IN NUMBER) RETURN VARCHAR2;
  -- the status a request form stores (p_kind leave / manual / overtime, p_id NULL: a new one): without attendance.approve
  -- pending; an approval or rejection of someone outside the user's departments, or of their own request, is refused
  FUNCTION request_status (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_id IN NUMBER, p_emp_code IN VARCHAR2,
                           p_status IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE request_remove (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_id IN NUMBER);    -- before one is removed
  -- several requests of a list decided at once (each checked as one; those not this user's left and counted);
  -- p_note: the approver's reason, told to the employee (DECISION_NOTE), the time of the decision kept (DECIDED_AT)
  FUNCTION request_decide_many (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_ids IN VARCHAR2, p_status IN VARCHAR2,
                                p_note IN NVARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  PROCEDURE request_open (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_id IN NUMBER);      -- before a form shows one
  FUNCTION pending_count (p_user IN VARCHAR2, p_kind IN VARCHAR2) RETURN NUMBER;       -- waiting, of those shown
  -- the greeting of the time of day (the settings' ui.greetings, else the program's) and the user's first name
  FUNCTION greeting (p_user IN VARCHAR2) RETURN VARCHAR2;
  -- the employee's attendance source by its name (hr.sources), and the note of a day recorded otherwise than it
  -- says (hr.source_methods, hr.verify_methods, hr.source_flag; hader/att_source.py note)
  FUNCTION source_name (p_emp IN VARCHAR2) RETURN VARCHAR2;
  -- how long a punch stayed in its terminal before it reached the server (the punch log's "arrived after")
  FUNCTION arrived_after (p_seconds IN NUMBER, p_lang IN VARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  -- terminals back after a silence with punches of a clock gone back to midnight (HDR_V_RETURN_PUNCHES), as JSON;
  -- the right time of one of them: the same difference to all (p_punch empty: the return is set aside)
  FUNCTION clock_returns (p_user IN VARCHAR2 DEFAULT NULL) RETURN CLOB;
  FUNCTION as_time (p IN VARCHAR2) RETURN DATE;     -- 'YYYY-MM-DD HH24:MI[:SS]' (or with T); NULL when it is not one
  FUNCTION clock_fix (p_user IN VARCHAR2, p_return IN NUMBER, p_punch IN NUMBER, p_right IN VARCHAR2,
                      p_ids IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  -- a leave beyond the HR system's balance: the warning (hr.balance_rule), else NULL
  FUNCTION balance_short (p_id IN NUMBER) RETURN NVARCHAR2;
  -- a month's lateness taken from a leave balance (hader/leave_moves.py): the month's movements made again as
  -- waiting (those posted stay), and the waiting ones posted through hr.ledger_proc (p_ids: those, else the month's)
  FUNCTION paused (p_day IN DATE) RETURN VARCHAR2;
  -- employees the HR link would not bring now (outside hr.employees_where), resigned ones with no punch on any
  -- terminal, and departments with no one: counted (p_apply N), or removed (Y: employees off the terminals too)
  FUNCTION employees_cleanup (p_user IN VARCHAR2, p_apply IN VARCHAR2 DEFAULT 'N') RETURN NVARCHAR2;     -- Y: within hr.deduct_pause
  FUNCTION moves_compute (p_user IN VARCHAR2, p_month IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION moves_post (p_user IN VARCHAR2, p_month IN VARCHAR2, p_ids IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  -- a leave out of its type's HR rules (hr.table_leave_rules, hr.leave_rule): the warning, else NULL
  FUNCTION leave_rules (p_id IN NUMBER) RETURN NVARCHAR2;
  -- what went beyond the limits of the employee's attendance type in the period (hader/hr_limits.py notes)
  FUNCTION limits_note (p_emp IN VARCHAR2, p_from IN DATE, p_to IN DATE) RETURN NVARCHAR2;
  FUNCTION source_note (p_emp IN VARCHAR2, p_day IN DATE) RETURN VARCHAR2;
  FUNCTION pairs_ok (p_text IN VARCHAR2, p_kind IN VARCHAR2) RETURN BOOLEAN;
  -- the attendance types of the HR schema (hr.att_owner: HR_ATTENDANCE_TYPES / _CONSTANT / _GROUPS) as shifts and
  -- each employee's schedules from p_since on (nothing before it changes), the Ramadan type in hr.ramadan's days,
  -- as the program does (hader/hr_attendance.py). p_apply 'N': only what it would do. system.admin. JSON.
  FUNCTION hr_types (p_user IN VARCHAR2, p_since IN DATE, p_apply IN VARCHAR2 DEFAULT 'N') RETURN CLOB;
  FUNCTION request_scope (p_user IN VARCHAR2) RETURN NVARCHAR2;      -- a department's approver: whose requests are shown
  -- a department's head and deputies (users.manage; no one names themselves but the system administrator; one
  -- head at a time). Returns the row's id.
  FUNCTION approver_save (p_user IN VARCHAR2, p_id IN NUMBER, p_dept_code IN VARCHAR2, p_username IN VARCHAR2,
                          p_kind IN VARCHAR2, p_start IN DATE, p_end IN DATE) RETURN NUMBER;
  PROCEDURE approver_delete (p_user IN VARCHAR2, p_id IN NUMBER);
  -- an account added in the app (users.manage); those of the program (SOURCE HADER) are the Hader server's
  PROCEDURE account_save (p_user IN VARCHAR2, p_username IN VARCHAR2, p_full_name IN NVARCHAR2, p_emp_code IN VARCHAR2,
                          p_permissions IN VARCHAR2, p_active IN VARCHAR2 DEFAULT 'Y');
  PROCEDURE account_delete (p_user IN VARCHAR2, p_username IN VARCHAR2);

  -- settings and health ----------------------------------------------------------------------
  -- the landing page of Hader in another application of the university (plug-in COM.HADER.LANDING) ------------
  FUNCTION today RETURN CLOB;          -- today at a glance: expected, present, late, absent, on leave, terminals
  -- the landing page in the university's systems (COM.HADER.LANDING): who the user is to Hader and the parts of
  -- APEX app 141 their permissions open (the same rules as its pages); nobody: nothing at all
  FUNCTION landing (p_user IN VARCHAR2) RETURN CLOB;
  FUNCTION landing_today (p_user IN VARCHAR2) RETURN CLOB;   -- today at a glance, for whoever may see attendance
  -- the dashboard (page 1) as the program's: today, the last 14 days, hours, departments, terminals, punches
  FUNCTION dashboard (p_user IN VARCHAR2) RETURN CLOB;
  -- the biometrics page (32): the terminals next to what is stored; p_fetch 'Y': all of them asked for all they hold
  FUNCTION bio_coverage (p_user IN VARCHAR2, p_fetch IN VARCHAR2 DEFAULT 'N') RETURN CLOB;
  -- the page of that application to go back to from APEX app 141 (its user menu, back to the home page): its id or alias and
  -- page, kept as apex.home; NULL to forget it
  PROCEDURE home (p_app IN VARCHAR2, p_page IN VARCHAR2);
  FUNCTION home_url (p_session IN VARCHAR2) RETURN VARCHAR2;   -- f?p=app:page:session, NULL when none is kept
  -- the employee portal of APEX app 141 (page My portal): the signed-in APEX user's own days from the database; their
  -- requests, leave balances and inbox through the Hader server (HADER_REQUESTS KIND = PORTAL, hader/apex_portal.py)
  FUNCTION me_code (p_user IN VARCHAR2) RETURN VARCHAR2;   -- the employee of an APEX user (account, e-mail or number)
  FUNCTION me (p_user IN VARCHAR2) RETURN CLOB;            -- who, today, today's punches, the last answer of Hader
  FUNCTION me_month (p_user IN VARCHAR2, p_ym IN VARCHAR2) RETURN CLOB;   -- YYYY-MM day by day and its totals
  FUNCTION me_ask (p_user IN VARCHAR2, p_action IN VARCHAR2, p_detail IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  FUNCTION me_reply (p_user IN VARCHAR2, p_req IN VARCHAR2) RETURN CLOB;  -- a request's state and Hader's answer
  -- the native pages of My portal (no script): a new request of the employee's own from a page's fields, checked here
  -- and written for the Hader server as me_ask writes it. p_kind leave / manual / overtime; p_day (and p_day2, a
  -- leave of days) YYYY-MM-DD; p_from / p_to HH:MI (a leave of hours, the time of a punch, an overtime); p_type the
  -- leave type; p_state 0 in, 1 out (a punch). Returns the request
  FUNCTION me_send (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_day IN VARCHAR2, p_day2 IN VARCHAR2 DEFAULT NULL,
                    p_from IN VARCHAR2 DEFAULT NULL, p_to IN VARCHAR2 DEFAULT NULL, p_type IN VARCHAR2 DEFAULT NULL,
                    p_state IN VARCHAR2 DEFAULT NULL, p_reason IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  FUNCTION me_cancel (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_id IN VARCHAR2) RETURN VARCHAR2;  -- one still waiting
  -- the requests, balances and inbox asked of the Hader server again, unless asked a moment ago (p_age seconds) or
  -- still waiting for it: the request, or NULL when none was written
  FUNCTION me_refresh (p_user IN VARCHAR2, p_age IN NUMBER DEFAULT 15) RETURN VARCHAR2;
  FUNCTION me_status (p_user IN VARCHAR2, p_req IN VARCHAR2) RETURN VARCHAR2;   -- NEW / RUNNING / DONE / FAILED
  FUNCTION settings RETURN CLOB;
  -- the terminals' server (one terminal, or every one accepted and on): a system administrator's; how many were sent
  -- the activation key of the free edition (HDR_LICENSE.set_key): a system administrator's; empty removes it
  PROCEDURE set_license (p_key IN VARCHAR2);
  FUNCTION point_server (p_host IN VARCHAR2, p_port IN VARCHAR2, p_restart IN VARCHAR2 DEFAULT 'Y',
                         p_sn IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  PROCEDURE set_value (p_key IN VARCHAR2, p_value IN NVARCHAR2);
  PROCEDURE demo (p_on IN VARCHAR2);   -- Y: load the sample company (HDR_DEMO), N: remove it

  -- punch lines kept aside with a database error saved again (HDR_ADMS.replay_rejects); for who controls terminals
  FUNCTION replay_rejects (p_user IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL, p_from IN DATE DEFAULT NULL) RETURN NUMBER;

  -- let an APEX parsing schema use the plug-ins and build pages on the Hader tables
  FUNCTION grant_to (p_schema IN VARCHAR2) RETURN VARCHAR2;
  -- the English of APEX app 141 (2.3.6): its words translated from HDR_I18N, then published as its English version
  -- (APEX_LANG: a language mapping the first time, the texts seeded, translated and published). Again after every
  -- import of the app. p_app NULL: the app of this workspace with the alias HADER (or ATTENDANCE). Returns
  -- 'texts translated / texts left in Arabic / the English version's application id'
  -- the English of one text of the app's code (a region's query, PL/SQL or HTML): its shown Arabic pieces by HDR_I18N
  -- (apex/i18n/code_i18n.py); code_missing: how many pieces had no English in the calls so far (Y: from now on)
  FUNCTION code_en (p_text IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION code_missing (p_reset IN VARCHAR2 DEFAULT 'N') RETURN NUMBER;
  FUNCTION publish_english (p_app IN NUMBER DEFAULT NULL) RETURN VARCHAR2;
  FUNCTION english (p_app IN NUMBER) RETURN VARCHAR2;     -- Y: the app has its English version (publish_english)
  -- the language of the APEX session asking (en / ar; outside APEX: ar), and a text of the app in it: its English
  -- from HDR_I18N in an English session, else the Arabic as it is (the words the app writes in its own code)
  FUNCTION lang RETURN VARCHAR2;
  -- the terminals as the pages count them: 'all' (enabled), 'online', 'waiting' (commands waiting for them). Once Hader
  -- owns the terminals (clock.owner = hader, its gateway exit) what Hader publishes (HADER_DEV_TERMINALS), else Oracle's
  FUNCTION terminals_count (p_what IN VARCHAR2) RETURN NUMBER;
  FUNCTION tr (p_ar IN NVARCHAR2) RETURN NVARCHAR2;
END HDR_UI;
/

-- ---------------------------------------------------------------- hdr_ai.pks
CREATE OR REPLACE PACKAGE HDR_AI AS
  -- Hader AI for Oracle APEX: AI services and an assistant for APEX 19.2 and later (as the Generative AI services of
  -- APEX 24 and later). Standalone: it compiles and works with or without the rest of Hader for Oracle APEX, on
  -- Oracle 11g and later; nothing of APEX is named at compile time (APEX_WEB_SERVICE and APEX_JSON are called by name).
  --
  -- A service is called from the user's browser (the database needs no network permission and no wallet; the key
  -- reaches the browsers of the users allowed to use it) or from the database (the key never leaves it; the database
  -- must reach the provider over HTTPS). The browser builds each request and reads each answer (hader-ai.js); the
  -- database keeps the services and the key, relays a request when the service is called from the database (rebuilt
  -- here: the service's own model, its tokens at most, the provider's chat and function tools only), and answers the
  -- assistant's questions about the data (tool) with the signed-in user's own permissions.
  --
  -- Who: in APEX always the signed-in user (whatever is passed), never a public one; outside APEX the schema's owner
  -- names the user, and nobody else may call it.
  -- Permissions: with Hader for Oracle APEX in the schema (HDR_UI), its accounts: ai.use to use a service and
  -- system.admin to change them; without it (Hader AI alone) the application decides (the page's and the region's
  -- authorization; the services region requires its own scheme).
  c_version CONSTANT VARCHAR2(10) := '1.0';
  -- the Web Credentials a service may use: their static id starts so (AI_OPENAI, AI_GEMINI): the workspace's other
  -- credentials are never sent to the address of an AI service. With APEX 21.2 and later the credential's Valid for
  -- URLs must also name the service's address.
  c_credential_prefix CONSTANT VARCHAR2(10) := 'AI_';
  -- one user's requests a minute to a service called from the database (when the service sets none), and questions
  -- about the data a minute
  c_requests_per_minute CONSTANT PLS_INTEGER := 20;
  c_lookups_per_minute  CONSTANT PLS_INTEGER := 120;
  -- the tokens of an answer when the service sets none, and how long one request to a provider may take (seconds)
  c_max_tokens CONSTANT PLS_INTEGER := 8192;
  c_timeout    CONSTANT PLS_INTEGER := 60;

  FUNCTION mode_ RETURN VARCHAR2;                                              -- HADER / APP
  FUNCTION ready RETURN VARCHAR2;                                              -- Y: an enabled service
  FUNCTION may_use (p_user IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;          -- Y / N
  FUNCTION may_admin (p_user IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;        -- Y / N

  -- the services for the page that manages them: everything but the keys (only whether one is kept, and its end)
  FUNCTION services (p_user IN VARCHAR2 DEFAULT NULL) RETURN CLOB;
  -- p_id NULL: a new one. p_key NULL: the key kept stays; '-': no key. A key or a credential stays with the address
  -- it was given for: a change of the provider or of the address (scheme, host and port) removes the key kept and
  -- the credential kept (p_credential_again 'Y': chosen again for the new address), and so does calling a service
  -- from the browser that was called from the database (its key was given never to leave it). Returns the id.
  FUNCTION save_service (p_user IN VARCHAR2, p_id IN NUMBER, p_static IN VARCHAR2, p_name IN VARCHAR2,
                         p_provider IN VARCHAR2, p_url IN VARCHAR2, p_model IN VARCHAR2, p_call IN VARCHAR2,
                         p_credential IN VARCHAR2, p_key IN VARCHAR2, p_tokens IN NUMBER, p_default IN VARCHAR2,
                         p_enabled IN VARCHAR2, p_per_minute IN NUMBER DEFAULT NULL,
                         p_credential_again IN VARCHAR2 DEFAULT 'N') RETURN NUMBER;
  PROCEDURE drop_service (p_user IN VARCHAR2, p_id IN NUMBER);
  PROCEDURE tested (p_user IN VARCHAR2, p_id IN NUMBER, p_result IN VARCHAR2);

  -- one service for a call (by its static id; NULL: the default one): its provider, address, model, where it is
  -- called from, and its key when it is called from the browser. An enabled one; p_test 'Y': a system
  -- administrator's test on the services page (a disabled one too)
  FUNCTION service (p_user IN VARCHAR2, p_static IN VARCHAR2, p_test IN VARCHAR2 DEFAULT 'N') RETURN CLOB;
  -- a request of a service called from the database (by its static id, as service): rebuilt, posted to the service's
  -- own address with its key, and its answer as the page reads it: the text and the tool calls, or the error
  FUNCTION relay (p_user IN VARCHAR2, p_static IN VARCHAR2, p_body IN CLOB, p_test IN VARCHAR2 DEFAULT 'N') RETURN CLOB;

  -- what the assistant may ask about the data here (comma separated): attendance, terminals; empty: nothing
  FUNCTION tools (p_user IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  -- one question about the data, as JSON, with the user's own permissions (a user who does not see the attendance
  -- sees only themself): day, people, find, employee, totals, terminals
  FUNCTION tool (p_user IN VARCHAR2, p_name IN VARCHAR2, p_a1 IN VARCHAR2 DEFAULT NULL, p_a2 IN VARCHAR2 DEFAULT NULL,
                 p_a3 IN VARCHAR2 DEFAULT NULL, p_a4 IN VARCHAR2 DEFAULT NULL, p_a5 IN VARCHAR2 DEFAULT NULL) RETURN CLOB;

  -- for PL/SQL (as APEX_AI.GENERATE): one answer of a service called from the database, in APEX for a user allowed
  -- to use it, outside APEX for the schema's owner only
  FUNCTION generate (p_prompt IN CLOB, p_system IN CLOB DEFAULT NULL, p_service IN VARCHAR2 DEFAULT NULL) RETURN CLOB;
END HDR_AI;
/

-- ---------------------------------------------------------------- hdr_demo.pks
CREATE OR REPLACE PACKAGE HDR_DEMO AS
  -- A sample company for trying the plug-ins before any terminal is connected: 2 areas, 4 departments,
  -- 36 employees, 5 terminals (one waiting for approval), the punches of the last weeks, leave and a holiday.
  -- While it is loaded the background job keeps it alive: today's punches arrive at their times.
  -- Everything it adds is marked (codes 9001.., DEMO..) and removed by clear. It refuses to mix with real data.
  -- With no Hader server publishing, it also fills the terminals' link tables (HADER_DEV_*: four sample terminals,
  -- areas, people, commands, logs, a beat kept fresh by tick) and answers the pages' terminal requests itself.
  -- p_public Y: the public demo (set_public).
  PROCEDURE load (p_days IN NUMBER DEFAULT 35, p_public IN VARCHAR2 DEFAULT NULL);
  PROCEDURE clear;   -- removes the sample, its link rows, and turns the public demo off
  PROCEDURE tick;   -- called by HDR_JOBS.tick while the sample is loaded
  PROCEDURE english_names;   -- the sample's employees named as this release names them, in Arabic and English
  -- the public demo (HDR_SETTINGS demo.public): Y = every account but the one turning it on (demo.admins) looks and
  -- tries but deletes nothing and changes no system setting, user or key (HDR_UI.visitor / guard); the sample is
  -- loaded again every night (reset, from HDR_JOBS.tick). N = off (the default of every installation).
  PROCEDURE set_public (p_on IN VARCHAR2);
  PROCEDURE reset;
  PROCEDURE terminals;                             -- the sample terminals in HADER_DEV_* (load does it)
  PROCEDURE answer (p_req IN NUMBER DEFAULT NULL); -- the open terminal requests answered: a demo, no terminal
END HDR_DEMO;
/

